"""
Advanced SubStation Alpha (.ass) Karaoke Subtitle Builder with \\k Tags
Outputs Aegisub/VLC/CapCut/FFmpeg compatible running-highlight karaoke subtitles.
"""
from typing import List
from .aligner import TimedLine

ASS_HEADER = """[Script Info]
; Script generated by Auto-Karaoke Maker
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
; Primary: Unsung text (White), Secondary: Sung text highlight (Vibrant Cyan & Gold), Outline: Deep Black
Style: KaraokePrimary, Arial, 54, &H00FFFFFF, &H0000FFFF, &H00000000, &H80000000, 1, 0, 0, 0, 100, 100, 1, 0, 1, 3, 2, 2, 80, 80, 90, 1
Style: KaraokeSecondary, Arial, 48, &H00FFFFFF, &H0000D7FF, &H00000000, &H80000000, 1, 0, 0, 0, 100, 100, 1, 0, 1, 3, 2, 2, 80, 80, 160, 1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""

def format_ass_time(seconds: float) -> str:
    hrs = int(seconds // 3600)
    mins = int((seconds % 3600) // 60)
    secs = int(seconds % 60)
    cs = int(round((seconds - int(seconds)) * 100))
    if cs >= 100:
        cs = 99
    return f"{hrs:d}:{mins:02d}:{secs:02d}.{cs:02d}"

class ASSBuilder:
    @staticmethod
    def build_ass_content(timed_lines: List[TimedLine]) -> str:
        lines = [ASS_HEADER.strip()]
        for idx, line in enumerate(timed_lines):
            # Alternating styles or dual-line display (odd/even)
            style = "KaraokePrimary" if idx % 2 == 0 else "KaraokeSecondary"
            
            # Build Karaoke tags: {\k<centiseconds>}word
            karaoke_text_parts = []
            for tw in line.words:
                cs = max(1, int(round(tw.duration * 100)))
                karaoke_text_parts.append(f"{{\\k{cs}}}{tw.word}")

            karaoke_str = " ".join(karaoke_text_parts)
            st_str = format_ass_time(line.start)
            en_str = format_ass_time(line.end)
            lines.append(f"Dialogue: 0,{st_str},{en_str},{style},,0,0,0,,{karaoke_str}")

        return "\n".join(lines) + "\n"

    @staticmethod
    def build_lrc_content(timed_lines: List[TimedLine]) -> str:
        """Enhanced LRC with word tags [mm:ss.xx]<mm:ss.xx>word."""
        lrc = ["[ti:Auto-Karaoke Track]", "[by:Auto-Karaoke Maker]"]
        for line in timed_lines:
            mins = int(line.start // 60)
            secs = line.start % 60
            word_parts = []
            for tw in line.words:
                w_m = int(tw.start // 60)
                w_s = tw.start % 60
                word_parts.append(f"<{w_m:02d}:{w_s:05.2f}> {tw.word}")
            lrc.append(f"[{mins:02d}:{secs:05.2f}] " + " ".join(word_parts))
        return "\n".join(lrc)
